Component({properties:{value:{type:null,value:''},disabled:Boolean,placeholder:String,maxlength:{type:Number,value:140},type:{type:String,value:'text'},password:Boolean,focus:Boolean},methods:{change(e){this.triggerEvent('input',e.detail);},blur(e){this.triggerEvent('blur',e.detail);},confirm(e){if(e.detail.key==='Enter')this.triggerEvent('confirm',{value:e.detail.value});}}});